import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import BulkBusiness from "@/components/CustomerManagement/Bulkupload/BulkBusiness.vue";
import BulkIndividual from "@/components/CustomerManagement/Bulkupload/BulkIndividual.vue";
import DeleteCustomer from "./DeleteCustomer.vue";
import { API, graphqlOperation } from "aws-amplify";
import { customer_function } from "@/graphql/mutations.js";
import { get_customer_transactions } from "@/graphql/queries";
import { getS3SignedUrl } from "@/mixins/S3GetStorageFile.js";
import { useDisplay } from "vuetify/lib/framework.mjs";
import SnackBar from "@/components/SnackBar.vue";
import * as XLSX from "xlsx";
export default {
  components: {
    SnackBar,
    BulkIndividual,
    DeleteCustomer,
    BulkBusiness
  },
  data: () => ({
    height: 0,
    currentPage: 1,
    itemsPerPage: 50,
    searchlist: "",
    b2btemplateurl: "",
    individualtemplateurl: "",
    deleteCustomerDialog: false,
    tableLoading: false,
    tableLoadingdata: false,
    selectedCustomer: null,
    CommonVuetifyObj: {},
    SnackBarComponent: {},
    customerItem: {},
    customerRecords: [],
    customerTransactions: [],
    excelHeaders: [],
    excelTableData: [],
    rowInfo: null,
    TableHeaders: [{
      title: "Legal Name",
      value: "legal_name"
    }, {
      title: "Amount",
      value: "balance"
    }, {
      title: "Actions",
      value: "actions"
    }],
    customerDetailsHeader: [{
      title: "Invoice No.",
      value: "invoice_no"
    }, {
      title: "Transaction Type",
      value: "transaction_type"
    }, {
      title: "Transaction Details",
      value: "transaction_details"
    }, {
      title: "Transaction Date",
      value: "transaction_date"
    }, {
      title: "Total Amount",
      value: "total_cost"
    }, {
      title: "Balance Amount",
      value: "balance_cost"
    }]
  }),
  computed: {
    filteredCustomers() {
      if (!this.searchlist) return this.customerRecords;
      const search = this.searchlist.toLowerCase();
      return this.customerRecords.filter(item => Object.values(item).filter(v => v !== null && v !== undefined).join(" ").toLowerCase().includes(search));
    },
    pageCount() {
      return Math.ceil(this.customerTransactions.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async mounted() {
    this.CommonVuetifyObj = useDisplay();
    await this.fetch_customers();
    if (this.customerRecords.length > 0) {
      this.selectedCustomer = {
        ...this.customerRecords[0]
      };
      await this.fetch_customer_transactions(this.customerRecords[0].customer_id, this.customerRecords[0].organization_id);
    }
  },
  methods: {
    async downloadFile(url, fileName) {
      if (!url) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: `No URL provided for ${fileName}`,
          timeout: 5000,
          Top: true
        };
        return;
      }
      try {
        const details = this.$store.getters.GetOrgDetails;
        const signedUrl = await getS3SignedUrl(url, details.s3_details);
        if (!signedUrl) {
          throw new Error("Failed to generate signed URL");
        }
        const response = await fetch(signedUrl);
        if (!response.ok) {
          throw new Error(`Network response was not ok: ${response.statusText}`);
        }
        const blob = await response.blob();
        const downloadUrl = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = downloadUrl;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        link.remove();
        window.URL.revokeObjectURL(downloadUrl);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "green",
          SnackbarText: `${fileName} downloaded successfully`,
          timeout: 5000,
          Top: true
        };
      } catch (error) {
        console.error("Error downloading the file:", error);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: `Failed to download ${fileName}: ${error.message}`,
          timeout: 5000,
          Top: true
        };
      }
    },
    async fetch_customers() {
      this.customerRecords = [];
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(customer_function, {
          input: {
            action_type: "LIST_CUSTOMER"
          }
        }));
        var response = JSON.parse(result.data.customer_function);
        if (response.Status === "SUCCESS") {
          this.b2btemplateurl = response.b2b_template_url;
          this.individualtemplateurl = response.indivisual_template_url;
          const details = this.$store.getters.GetOrgDetails;
          const signedUrl = await getS3SignedUrl(response.url, details.s3_details);
          // console.log(details.s3_details,'details.s3_detailsLisy');
          // console.log(signedUrl,'signedUrl');
          if (signedUrl) {
            let updatedCustomer = await this.fetch_S3_file(signedUrl);
            this.customerRecords = updatedCustomer.sort((a, b) => a.legal_name.localeCompare(b.legal_name));
          }
          this.tableLoading = false;
        } else {
          this.b2btemplateurl = response.b2b_template_url || "";
          this.individualtemplateurl = response.indivisual_template_url || "";
          this.customerRecords = [];
          this.tableLoading = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: "Failed to fetch customers",
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.b2btemplateurl = "";
        this.individualtemplateurl = "";
        this.customerRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "Error fetching customers",
          timeout: 5000,
          Top: true
        };
      }
    },
    async fetch_customer_transactions(customer_id, organization_id) {
      this.customerTransactions = [];
      this.tableLoadingdata = true;
      try {
        // console.log("Fetching transactions for:", {
        //   customer_id,
        //   organization_id,
        // });
        let result = await API.graphql(graphqlOperation(get_customer_transactions, {
          customer_id: customer_id,
          organization_id: organization_id,
          nextToken: null,
          limit: 15
        }));
        this.tableLoadingdata = false;
        let response = JSON.parse(result.data.get_customer_transactions);
        this.customerTransactions = response.items || [];
        this.totalItems = this.customerTransactions.length;
        // console.log("Fetched customerTransactions:", this.customerTransactions);
      } catch (error) {
        this.customerTransactions = [];
        this.totalItems = 0;
        this.tableLoadingdata = false;
        console.error("Error fetching transactions:", error);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Error fetching transactions",
          timeout: 5000,
          Top: true
        };
      }
    },
    async fetch_S3_file(value) {
      try {
        const response = await fetch(value);
        if (!response.ok) {
          throw new Error(`Failed to fetch the file: ${response.statusText} (Status Code: ${response.status})`);
        }
        if (!response.headers.get("Content-Type").includes("application/json")) {
          throw new Error("The file is not in JSON format");
        }
        const responseData = await response.text();
        try {
          return JSON.parse(responseData);
        } catch (jsonError) {
          throw new Error("Error parsing JSON response: " + jsonError.message);
        }
      } catch (error) {
        console.error("Error fetching file:", error);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Error fetching file: " + error.message,
          timeout: 5000,
          Top: true
        };
        return [];
      }
    },
    Add_customer() {
      this.$router.push("/home/CreateCustomer");
    },
    Edit_Customer(item) {
      this.$router.push("/home/EditCustomer");
      this.$store.commit("SetcustomerData", item);
    },
    View_Customer(item) {
      this.$router.push("/home/ViewCustomer");
      this.$store.commit("SetcustomerData", item);
    },
    Delete_customer(item) {
      this.deleteCustomerDialog = true;
      this.rowInfo = item;
    },
    download_item() {
      const headers = ["Legal Name of Business*", "Brand Name", "Address 1 *", "Address 2", "GST Id", "PAN Id", "CIN Number", "Primary Name*", "Primary Email ID*", "Primary Country Code*", "Primary Contact Number*", "Primary Designation*"];
      let firstName = this.$store.getters.GetUserObj?.organization?.organization_team_id || "";
      let fileName = firstName ? ` ${firstName}_Members Template.xlsx` : "Members Template.xlsx";
      const ws = XLSX.utils.aoa_to_sheet([headers]);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
      XLSX.writeFile(wb, fileName);
    },
    handleSuccess({
      results,
      header
    }) {
      this.excelTableData = results;
      this.$router.push("/home/UploadCustomer");
      this.excelHeaders = header;
      let customerData = {
        excelHeaders: this.excelHeaders,
        excelTableData: this.excelTableData,
        customerType: "INDIVISUAL"
      };
      this.$store.commit("SetcustomerDetails", customerData);
    },
    handleSuccessbusiness({
      results,
      header
    }) {
      this.excelTableData = results;
      this.$router.push("/home/UploadCustomer");
      this.excelHeaders = header;
      let customerData = {
        excelHeaders: this.excelHeaders,
        excelTableData: this.excelTableData,
        customerType: "BUSINESS"
      };
      this.$store.commit("SetcustomerDetails", customerData);
    },
    openDetails(event, {
      item
    }) {
      // console.log("Row clicked, item:", item);
      this.selectedCustomer = {
        ...item
      };
      // console.log("Updated selectedCustomer:", this.selectedCustomer);
      this.fetch_customer_transactions(item.customer_id, item.organization_id);
    },
    beforeUpload(file) {
      const isLt1M = file.size / 1024 / 1024 < 5;
      if (isLt1M) {
        return true;
      }
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: "File size must be less than 5MB",
        timeout: 5000,
        Top: true
      };
      return false;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.deleteCustomerDialog = false;
      this.fetch_customers().then(() => {
        if (this.selectedCustomer && this.rowInfo && this.selectedCustomer.customer_id === this.rowInfo.customer_id) {
          this.selectedCustomer = this.customerRecords.length > 0 ? {
            ...this.customerRecords[0]
          } : null;
          // console.log("Post-delete selectedCustomer:", this.selectedCustomer);
          if (this.selectedCustomer) {
            this.fetch_customer_transactions(this.selectedCustomer.customer_id, this.selectedCustomer.organization_id);
          } else {
            this.customerTransactions = [];
            this.totalItems = 0;
          }
        }
      });
    },
    async export_item() {
      try {
        const result = await API.graphql(graphqlOperation(export_customer_data, {
          input: {
            action_type: "EXPORT_CUSTOMER"
          }
        }));
        const response = JSON.parse(result.data.export_customer_data);
        if (response.Status === "SUCCESS" && response.url) {
          await this.downloadFile(response.url, "Exported_Customers.xlsx");
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: "Failed to export customers",
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        console.error("Error exporting customers:", error);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Error exporting customers",
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
